package com.oms.order.service;
import org.junit.jupiter.api.*;
import java.util.*;
import com.ruoyi.common.core.domain.R;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

class RefundParcelAutomationTest {
    RefundGoodsServiceTest f;RefundParcelAutomation auto;RefundParcelPolicy policy;RefundParcelWorkspace workspace;long plan;
    @BeforeAll static void start(){RefundGoodsServiceTest.start();}
    @BeforeEach void setup(){f=new RefundGoodsServiceTest();f.setup();f.f.db.update("DELETE FROM oms_refund_parcel_config");plan=f.create(1);policy=new RefundParcelPolicy();policy.refunds=f.f.refunds;policy.catalog=mock(OrderCatalog.class);policy.returns=f.goods.returns;when(policy.returns.parcelCapabilities(anyString(),anyString())).thenReturn(R.ok(Collections.singletonList(m("store_code","V","usable",1,"shared_return_waybill",1,"shared_return_append",1))));Map<String,Object> rules=RefundParcelPolicy.defaults();rules.putAll(m("auto_enabled",1,"store_codes",Arrays.asList("V")));policy.save("VERIFY",1,rules,"test");workspace=new RefundParcelWorkspace();workspace.refunds=f.f.refunds;workspace.policy=policy;workspace.returns=f.goods.returns;
        auto=new RefundParcelAutomation();auto.refunds=f.f.refunds;auto.policies=policy;auto.parcels=workspace;auto.goods=f.goods;auto.returns=f.goods.returns;when(auto.returns.parcels(anyString(),anyLong(),anyString())).thenReturn(R.ok(Collections.emptyList()));when(auto.returns.parcelCandidates(anyString(),anyString(),anyString(),anyString())).thenReturn(R.ok(Collections.emptyList()));when(auto.returns.attachParcel(anyString(),anyLong(),anyMap(),anyString())).thenReturn(R.ok(m("id",1,"parcel_sn","RPK_TEST")));
    }
    @AfterEach void cleanup(){f.cleanup();}
    void logistics(){Map<String,Object> b=f.f.refunds.business("VERIFY",f.refund,false),p=f.f.refunds.platform("VERIFY",number(b,"platform_refund_id"),false),raw=parse(text(p,"payload"));raw.put("company_name","顺丰速运");raw.put("sid","WAYBILL");f.f.db.update("UPDATE oms_platform_refund SET payload=? WHERE id=?",encode(m("refund_get_response",m("refund",raw))),p.get("id"));}
    @Test void missingLogisticsWaitsWithoutCreatingWarehouseDocument(){auto.process("VERIFY",f.refund);assertEquals("WAIT_LOGISTICS",f.plan(plan).get("parcel_state"));verify(auto.returns,never()).attachParcel(anyString(),anyLong(),anyMap(),anyString());verify(auto.returns,never()).prepare(anyString(),anyLong(),anyMap(),anyString());}
    @Test void readyPlanUsesTrustedShopIdentityAndSavedPolicySnapshot(){logistics();auto.process("VERIFY",f.refund);assertEquals("LINKED",f.plan(plan).get("parcel_state"));verify(auto.returns).attachParcel(eq("VERIFY"),eq(plan),argThat(body->"AUTO".equals(body.get("association_mode"))&&number(body,"channel_id")==1&&"SF".equals(body.get("carrier_code"))&&number(obj(encode(body.get("policy"))),"revision")==1),anyString());verify(auto.returns,never()).prepare(anyString(),anyLong(),anyMap(),anyString());}
    @Test void latePlatformLogisticsMakesPreviouslyWaitingPlanDueImmediately(){auto.process("VERIFY",f.refund);Map<String,Object> next=f.f.source(2,"2.00","SUCCESS"),raw=parse(text(next,"jdp_response"));raw.put("company_name","SF");raw.put("sid","LATE_WAYBILL");next.put("jdp_response",encode(m("refund_get_response",m("refund",raw))));f.f.ingest(next);assertEquals(1,f.f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan WHERE id=? AND parcel_next_attempt<=NOW()",Integer.class,plan));auto.scan("VERIFY");assertEquals("LINKED",f.plan(plan).get("parcel_state"));}
    @Test void remoteFailureBecomesVisiblePendingIssueAndDoesNotLoseThePlan(){logistics();when(auto.returns.attachParcel(anyString(),anyLong(),anyMap(),anyString())).thenThrow(new IllegalArgumentException("仓库不支持追加"));auto.process("VERIFY",f.refund);assertEquals("NEED_CHECK",f.plan(plan).get("parcel_state"));assertTrue(text(f.plan(plan),"parcel_error").contains("仓库不支持追加"));assertNull(f.plan(plan).get("lease_token"));}
    @Test void concurrentAutomaticTriggerDoesNotOverrideActiveWorkerOrReportFalseFailure(){logistics();f.f.db.update("UPDATE oms_refund_return_plan SET parcel_lease_token='other_worker',parcel_lease_until=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE id=?",plan);auto.process("VERIFY",f.refund);assertEquals("WAIT_LOGISTICS",f.plan(plan).get("parcel_state"));assertEquals("other_worker",f.plan(plan).get("parcel_lease_token"));verify(auto.returns,never()).attachParcel(anyString(),anyLong(),anyMap(),anyString());}
    @Test void acceptedCommonThkCannotBeExtendedByAutomaticTrigger(){logistics();when(auto.returns.parcelCandidates(anyString(),anyString(),anyString(),anyString())).thenReturn(R.ok(Collections.singletonList(m("id",70,"parcel_sn","RPK_FROZEN","channel_id",1,"platform_tid",f.f.refunds.business("VERIFY",f.refund,false).get("platform_tid"),"store_code","V","carrier_code","SF","waybill","WAYBILL","dispatched",1,"receipt_count",0))));auto.process("VERIFY",f.refund);assertEquals("NEED_CHECK",f.plan(plan).get("parcel_state"));assertEquals("THK_FROZEN",text(obj(f.plan(plan).get("parcel_issue")),"code"));verify(auto.returns,never()).attachParcel(anyString(),anyLong(),anyMap(),anyString());}
    @Test void collectionWindowPreventsImmediateAutomaticDispatch(){logistics();Map<String,Object> rules=policy.get("VERIFY",1);rules.put("auto_dispatch",1);policy.save("VERIFY",1,rules,"test");Map<String,Object> parcel=m("id",70,"parcel_sn","RPK_COLLECT","carrier_code","SF","waybill","WAYBILL","store_code","V","dispatch_after",java.time.LocalDateTime.now().plusMinutes(5).format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")),"members",Collections.singletonList(m("plan_id",plan,"generation",1)));when(auto.returns.parcels(anyString(),anyLong(),anyString())).thenReturn(R.ok(Collections.singletonList(parcel)));auto.process("VERIFY",f.refund);assertEquals("LINKED",f.plan(plan).get("parcel_state"));verify(auto.returns,never()).prepare(anyString(),anyLong(),anyMap(),anyString());}

}
